selected.compute:
options=read('/input/options')
result=None
for combo in combinations(options,3):
 if all(combo[i]['owner']!=combo[j]['owner'] for i in range(3) for j in range(i+1,3)):
  ids=[c['id'] for c in combo]
  total_quality=0
  total_cost=0
  requires_ok=True
  for c in combo:
   total_quality+=c['quality']
   total_cost+=c['cost']
   for r in c['requires']:
    if r not in ids:
     requires_ok=False
     break
   if not requires_ok:
    break
  if requires_ok and total_quality>=15 and total_cost<=18:
   result=ids
   break
if result is None:
 result=[]

selected.effects:
existing=read('/output/selection')
if existing is None and result!=[]:
 write('/output/selection',result)
 send('report','team',result)
 if exists('/tmp/cache'):
  delete('/tmp/cache')
